{
  "implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    n = len(segments)

    minima = [seg['minimum'] for seg in segments]
    capacities = [seg['capacity'] for seg in segments]
    importances = [seg['importance'] for seg in segments]
    names = [seg['name'] for seg in segments]

    total_min = sum(minima)
    total_cap = sum(capacities)
    if budget < total_min or budget > total_cap:
        raise ValueError('Budget out of range')

    for i in range(n):
        if minima[i] > capacities[i]:
            raise ValueError('Minimum exceeds capacity')

    allocations = minima[:]
    current = allocations[:]
    remaining = budget - sum(current)

    while remaining > 0:
        best_idx = -1
        best_score = -1.0
        for i in range(n):
            if current[i] < capacities[i]:
                score = importances[i] / (current[i] + 1)
                if score > best_score:
                    best_score = score
                    best_idx = i
        if best_idx == -1:
            raise ValueError('Cannot allocate remaining budget')
        allocations[best_idx] += 1
        current[best_idx] += 1
        remaining -= 1

    by_name = {name: alloc for name, alloc in zip(names, allocations)}
    return {
        'allocations': allocations,
        'by_name': by_name,
        'total': sum(allocations)
    }"
}
